SELECT name, dept, salary,
  RANK() OVER (PARTITION BY dept ORDER BY salary DESC) AS r
FROM employees;

SELECT day, amount,
  SUM(amount) OVER (
    ORDER BY day
    ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
  ) AS running_total
FROM sales;

WITH top_depts AS (
  SELECT dept FROM employees GROUP BY dept HAVING COUNT(*) > 10
)
SELECT * FROM employees WHERE dept IN (SELECT dept FROM top_depts);

SELECT DISTINCT salary FROM emp e1
WHERE N-1 = (
  SELECT COUNT(DISTINCT salary) FROM emp e2
  WHERE e2.salary > e1.salary
);

SELECT DISTINCT salary FROM emp
ORDER BY salary DESC
LIMIT 1 OFFSET N-1;

SELECT salary FROM (
  SELECT salary, DENSE_RANK() OVER (ORDER BY salary DESC) AS r
  FROM emp
) t WHERE r = N;

INSERT INTO users (id, name) VALUES (1, 'Asha');
UPDATE users SET name = 'Asha K' WHERE id = 1;
DELETE FROM users WHERE id = 1;

SELECT DISTINCT city FROM customers;
SELECT o.id, c.name AS customer
FROM orders o JOIN customers c ON o.cid = c.id;

SELECT o.id, c.name
FROM orders o
INNER JOIN customers c ON o.customer_id = c.id;

SELECT e.name AS employee, m.name AS manager
FROM employees e
JOIN employees m ON e.manager_id = m.id;

-- correlated: references outer e
SELECT e.name FROM employees e
WHERE e.salary > (
  SELECT AVG(salary) FROM employees
  WHERE dept = e.dept        -- depends on e
);
